package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/** What a person shows of their statements: how many they have had, and the last one's due-total
 *  (null when it was n/a) and date (both null with none). */
public record StatementSummary(int count, BigDecimal lastDueTotal, LocalDate lastDate) {

    public static final StatementSummary NONE = new StatementSummary(0, null, null);

    /** The summary of one person's statements, oldest first. */
    public static StatementSummary of(List<PersonStatement> statements) {
        if (statements.isEmpty()) {
            return NONE;
        }
        PersonStatement last = statements.get(statements.size() - 1);
        return new StatementSummary(statements.size(), last.getDueTotal(), last.getTakenOn());
    }
}
-- People kept on a sheet, listed in the order they were added (by id).
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- The version of a person, raised on every save; an edit names the version it loaded and is
-- refused when someone else has saved the person since.
ALTER TABLE person ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
-- A person can be retired from a date: they count as retired at once, whatever the date, and no
-- claim dated after it can be added for them (or moved there). Null while not retired.
ALTER TABLE person ADD COLUMN retired_from DATE;
-- A person can be put on hold and taken off it again: while held, their OPEN claims count in no
-- live total (their SETTLED ones still do).
ALTER TABLE person ADD COLUMN held BOOLEAN NOT NULL DEFAULT FALSE;
-- A person's patrons: other people on the same sheet, each named at most once. A person shows
-- their patrons' names and their backing (the patrons' due-totals added up, n/a ones skipped).
CREATE TABLE person_patron (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CHECK (patron_id <> person_id),
    CONSTRAINT person_patron_once UNIQUE (person_id, patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, id);

