272	        this.patronErrors.set({});
273	        this.quickForm.reset({ name: '', amount: '' });
274	        this.quickError.set(null);
275	        this.people.set([]);
276	        this.claims.set([]);
277	        this.rates.set([]);
278	        this.periods.set([]);
279	        if (id) void this.read(id);
280	      });
281	    });
282	  }
283	
284	  protected edit(p: Person): void {
285	    this.error.set(null);
286	    this.editingId.set(p.id);
287	    this.editingVersion = p.version;
288	    this.form.setValue({ name: p.name, grade: p.grade });
289	  }
290	
291	  protected claimsOf(personId: number): Claim[] {
292	    return this.byPerson().get(personId)?.claims ?? [];
293	  }
294	
295	  protected overdueOf(personId: number): { count: number; cents: number } {
296	    return this.overdueByPerson().get(personId) ?? { count: 0, cents: 0 };
297	  }
298	
299	  protected claimedBy(personId: number): string {
300	    return money(this.byPerson().get(personId)?.cents ?? 0);
301	  }
302	
303	  /** Every rate the sheet has for a grade. */
304	  protected ratesOf(grade: string): Rate[] {
305	    return this.rates().filter((r) => r.grade === grade);
306	  }
307	
308	  protected dueOf(p: Person): string {
309	    const due = this.dueByPerson().get(p.id);
310	    return due === null || due === undefined ? 'n/a' : money(due);
311	  }
312	
313	  /** The person's patrons' names, sorted, comma and space separated. */
314	  protected patronNamesOf(p: Person): string {
315	    const names = this.namesById();
316	    return p.patronIds.map((id) => names.get(id) ?? '').filter((n) => n).sort().join(', ');
317	  }
318	
319	  /** The person's patrons' due-totals added up, skipping n/a; 0.00 with no patrons. */
320	  protected backingOf(p: Person): string {
321	    const dues = this.dueByPerson();
322	    return money(p.patronIds.reduce((sum, id) => sum + (dues.get(id) ?? 0), 0));
323	  }
324	
325	  /** The people the person may name as a patron: everyone else on the sheet. */
326	  protected patronChoicesFor(p: Person): Person[] {
327	    return this.people().filter((o) => o.id !== p.id);
328	  }
329	
330	  /** Name another person as the person's patron; the row then shows them among its patrons. */
331	  protected async addPatron(p: Person, patronId: string): Promise<void> {
332	    this.clearRowError(p.id);
333	    const sheetId = this.session.sheetId();
334	    if (!sheetId) return;
335	    if (!patronId) {
336	      this.patronErrors.update((errs) => ({ ...errs, [p.id]: 'Choose a patron.' }));
337	      return;
338	    }
339	    try {
340	      const saved = await this.api.addPatron(sheetId, p.id, Number(patronId));
341	      if (this.session.sheetId() === sheetId) this.taken(saved);
342	    } catch (e) {
343	      this.patronErrors.update((errs) => ({ ...errs, [p.id]: patronError(e) }));
344	    }
345	  }
346	
347	  /** The last statement's due-total: blank with none, n/a when it was n/a. */
348	  protected statedTotalOf(p: Person): string {
349	    return p.statementCount === 0 ? '' : (p.statedTotal ?? 'n/a');
350	  }
351	
352	  /** Take a statement of a person; the row then shows it and their claims as bound now. */
353	  protected async statement(p: Person): Promise<void> {
354	    this.clearRowError(p.id);
355	    const sheetId = this.session.sheetId();
356	    if (!sheetId) return;
357	    try {
358	      const taken = await this.api.statement(sheetId, p.id);
359	      if (this.session.sheetId() !== sheetId) return;
360	      this.taken(taken.person);
361	      this.claims.update((cs) => [...cs.filter((c) => c.personId !== p.id), ...taken.claims].sort((a, b) => b.id - a.id));
362	    } catch (e) {
363	      this.rowErrors.update((errs) => ({ ...errs, [p.id]: statementError(e) }));
364	    }
365	  }
366	
367	  /** Retire a person from a date (blank: the sheet's today); the row then shows them retired. */
368	  protected async retire(p: Person, from: string): Promise<void> {
369	    this.clearRowError(p.id);
370	    const sheetId = this.session.sheetId();
371	    if (!sheetId) return;
372	    try {
373	      const retired = await this.api.retire(sheetId, p.id, from.trim());
374	      if (this.session.sheetId() === sheetId) this.taken(retired);
375	    } catch (e) {
376	      this.rowErrors.update((errs) => ({ ...errs, [p.id]: retireError(e) }));
377	    }
378	  }
379	
380	  /** Put a person on hold, or take them off it when held; the row then shows the new state. */
381	  protected async hold(p: Person): Promise<void> {
382	    this.clearRowError(p.id);
383	    const sheetId = this.session.sheetId();
384	    if (!sheetId) return;
385	    try {
386	      const saved = await this.api.hold(sheetId, p.id, !p.held);
387	      if (this.session.sheetId() === sheetId) this.taken(saved);
388	    } catch (e) {
389	      this.rowErrors.update((errs) => ({ ...errs, [p.id]: holdError(e) }));
390	    }
391	  }
392	
393	  protected clearRowError(id: number): void {
394	    this.rowErrors.update(({ [id]: _, ...rest }) => rest);
395	    this.patronErrors.update(({ [id]: _, ...rest }) => rest);
396	  }
397	
398	  /** Take in a rate just set, in place of the grade's old one for the same from-date. */
399	  protected rateSaved(rate: Rate): void {
400	    this.rates.update((rs) => [...rs.filter((r) => r.grade !== rate.grade || r.from !== rate.from), rate]);
401	  }
402	
403	  /** Take in a period just added or closed, in its place by from-date. */
404	  protected periodSaved(period: Period): void {
405	    this.periods.update((ps) => [...ps.filter((p) => p.id !== period.id), period].sort((a, b) => a.from.localeCompare(b.from)));
406	  }
407	
408	  /** Take in a claim just added (listed first, as the newest) or saved (in its place). */
409	  protected claimSaved(claim: Claim): void {
410	    this.claims.update((cs) => cs.some((c) => c.id === claim.id)
411	      ? cs.map((c) => (c.id === claim.id ? claim : c))
412	      : [claim, ...cs].sort((a, b) => b.id - a.id));
413	  }
414	
415	  protected cancel(): void {
416	    this.reset();
417	  }
418	
419	  protected async submit(): Promise<void> {
420	    if (this.submitting) return;
421	    this.error.set(null);
422	    const sheetId = this.session.sheetId();
423	    if (!sheetId) return;
424	    const value = this.form.getRawValue();
425	    if (!value.name.trim()) {
426	      this.error.set('Enter a name.');
427	      return;
428	    }
429	    if (!(GRADES as readonly string[]).includes(value.grade)) {
430	      this.error.set('Choose a grade.');
431	      return;
432	    }
433	    const editing = this.editingId();
434	    this.submitting = true;
435	    try {
436	      if (editing === null) {
437	        const added = await this.api.add(sheetId, value);
438	        if (this.session.sheetId() === sheetId) this.people.update((ps) => [...ps, added]);
439	      } else {
440	        const saved = await this.api.update(sheetId, editing, { ...value, version: this.editingVersion });
441	        if (this.session.sheetId() === sheetId) this.taken(saved);
442	      }
443	      this.reset();
444	    } catch (e) {
445	      if (editing !== null && isStale(e)) await this.reloadEditing(sheetId, editing);
446	      this.error.set(personError(e));
447	    } finally {
448	      this.submitting = false;
449	    }
450	  }
451	
452	  /** Quick-add a DRAFT claim by name; the person is added first (grade A) when new. */
453	  protected async quickAdd(): Promise<void> {
454	    if (this.quickAdding) return;
455	    this.quickError.set(null);
456	    const sheetId = this.session.sheetId();
457	    if (!sheetId) return;
458	    const value = this.quickForm.getRawValue();
459	    const amount = value.amount.trim();
460	    if (!value.name.trim()) {
461	      this.quickError.set('Enter a name.');
462	      return;
463	    }
464	    if (!AMOUNT_PATTERN.test(amount)) {
465	      this.quickError.set('Enter an amount of 0.00 or more with up to two decimals.');
466	      return;
467	    }
468	    this.quickAdding = true;
469	    try {
470	      const added = await this.claimsApi.quickAdd(sheetId, { name: value.name, amount });
471	      if (this.session.sheetId() !== sheetId) return;
472	      if (added.personAdded) this.people.update((ps) => [...ps.filter((p) => p.id !== added.person.id), added.person]);
473	      else this.taken(added.person);
474	      this.claimSaved(added.claim);
475	      this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
476	    } catch (e) {
477	      this.quickError.set(quickAddError(e));
478	    } finally {
479	      this.quickAdding = false;
480	    }
481	  }
482	
483	  /** Take in a person as the store now holds them, in place of the old row. */
484	  private taken(person: Person): void {
485	    this.people.update((ps) => ps.map((p) => (p.id === person.id ? person : p)));
486	  }
487	
488	  /** After a save refused as stale, show the person's current values in the row and the open
489	   *  editor, which then edits that version. */
490	  private async reloadEditing(sheetId: string, id: number): Promise<void> {
491	    try {
492	      const current = await this.api.get(sheetId, id);
493	      if (this.session.sheetId() !== sheetId || this.editingId() !== id) return;
494	      this.taken(current);
495	      this.editingVersion = current.version;
496	      this.form.setValue({ name: current.name, grade: current.grade }, { emitEvent: false });
497	    } catch {
498	      // the error shown already says the save was refused
499	    }
500	  }
501	
502	  private reset(): void {
503	    this.editingId.set(null);
504	    this.form.reset({ name: '', grade: 'A' });
505	    this.error.set(null);
506	  }
507	
508	  private async read(sheetId: string): Promise<void> {
509	    const seq = ++this.readSeq;
510	    try {
511	      const [people, claims, rates, periods] = await Promise.all([
512	        this.api.list(sheetId), this.claimsApi.list(sheetId), this.ratesApi.list(sheetId), this.periodsApi.list(sheetId)]);
513	      if (seq === this.readSeq) {
514	        this.rates.set(rates);
515	        this.periods.set(periods);
516	        this.claims.set(claims);
517	        this.people.set(people);
518	      }
519	    } catch {
520	      if (seq === this.readSeq) this.error.set('Something went wrong loading people; try again.');
521	    }
522	  }
523	}
